CREATE TABLE private.marketplace_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text UNIQUE NOT NULL CHECK(length(sku) BETWEEN 2 AND 60),title text NOT NULL CHECK(length(title) BETWEEN 2 AND 150),description text NOT NULL DEFAULT '' CHECK(length(description)<=5000),category text NOT NULL DEFAULT 'Marketing materials' CHECK(length(category)<=100),price_cents integer NOT NULL CHECK(price_cents BETWEEN 1 AND 100000000),cost_cents integer CHECK(cost_cents BETWEEN 0 AND 100000000),shipping_cents integer NOT NULL DEFAULT 0 CHECK(shipping_cents BETWEEN 0 AND 10000000),minimum_quantity integer NOT NULL DEFAULT 1 CHECK(minimum_quantity BETWEEN 1 AND 1000),stock integer CHECK(stock>=0),supplier_id uuid REFERENCES private.marketplace_suppliers(id),supplier_sku text NOT NULL DEFAULT '' CHECK(length(supplier_sku)<=100),fulfillment text NOT NULL DEFAULT 'dropship' CHECK(fulfillment IN ('dropship','wholesale','print_on_demand')),lead_time text NOT NULL DEFAULT '' CHECK(length(lead_time)<=100),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')),image bytea,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.marketplace_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id),customer_name text NOT NULL,customer_email text NOT NULL,business_name text NOT NULL DEFAULT '',instructions text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','paid','processing','shipped','delivered','cancelled')),payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid','failed','refunded','partially_refunded')),subtotal_cents integer NOT NULL,shipping_cents integer NOT NULL,tax_cents integer NOT NULL DEFAULT 0,total_cents integer NOT NULL,stripe_session_id text UNIQUE,payment_intent_id text UNIQUE,refund_id text,refund_status text,refunded_cents integer NOT NULL DEFAULT 0,shipping_address jsonb,tracking_number text NOT NULL DEFAULT '',tracking_url text NOT NULL DEFAULT '',carrier text NOT NULL DEFAULT '',private_notes text NOT NULL DEFAULT '',inventory_reserved boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL DEFAULT now()+interval '31 minutes',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz);
CREATE INDEX marketplace_orders_user ON private.marketplace_orders(user_id,created_at DESC);
CREATE INDEX marketplace_orders_status ON private.marketplace_orders(status,created_at DESC);
CREATE TABLE private.marketplace_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES private.marketplace_orders(id),product_id uuid NOT NULL REFERENCES private.marketplace_products(id),title text NOT NULL,sku text NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 1000),price_cents integer NOT NULL,cost_cents integer,supplier_id uuid REFERENCES private.marketplace_suppliers(id),supplier_sku text NOT NULL DEFAULT '',fulfillment text NOT NULL);
CREATE INDEX marketplace_items_order ON private.marketplace_order_items(order_id);
CREATE TABLE private.marketplace_order_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES private.marketplace_orders(id),actor_id uuid,action text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.marketplace_webhook_events(id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO private.platform_settings(key,value) VALUES('marketplace','{"checkoutEnabled":false}');
REVOKE ALL ON private.marketplace_products,private.marketplace_orders,private.marketplace_order_items,private.marketplace_order_activity,private.marketplace_webhook_events FROM public,anon,authenticated;
ALTER TABLE private.marketplace_order_items ADD COLUMN stock_reserved boolean NOT NULL DEFAULT false;
ALTER TABLE private.marketplace_products ADD COLUMN revision integer NOT NULL DEFAULT 0;
CREATE TABLE private.marketplace_refunds(payment_intent_id text PRIMARY KEY,amount_cents integer NOT NULL CHECK(amount_cents>=0),updated_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON private.marketplace_refunds FROM public,anon,authenticated;
